with with_latest as (select s.*, latest.web_event_page from sessions s join lateral (select c.page as web_event_page from web_events c where c.session_id = s.id order by c.event_time desc, c.id desc limit 1) latest on true) select customer_id, web_event_page, count(*) as event_count, max(started_at) as last_seen, count_if(country = 'DE') as de_events, grouping_id() as gid from with_latest group by grouping sets ((customer_id, web_event_page), (customer_id), ()) order by event_count asc;
